<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='attendance';$pageTitle='Approved Attendance';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$rows=[];if(fo_has_table($conn,'finance_attendance_approved')){$r=$conn->query("SELECT faa.*,u.first_name,u.last_name,u.email FROM finance_attendance_approved faa JOIN users u ON u.id=faa.participant_id WHERE faa.approval_status='approved' ORDER BY faa.attendance_date DESC LIMIT 500");if($r)while($x=$r->fetch_assoc())$rows[]=$x;}$cfg=fo_config($conn);require __DIR__.'/_layout_start.php';?>
<div class="fo-page-header"><div><span>Payment Source Data</span><h2>Approved Attendance</h2><p>Only approved attendance is eligible to feed stipend calculations.</p></div><a class="fo-btn fo-btn--primary" href="<?= url('finance_officer/prepare_schedule.php') ?>"><i class="fas fa-file-circle-plus"></i> Prepare Schedule</a></div><div class="fo-card"><div class="fo-card__header"><h3>Approved Attendance Register</h3><p>Default rate <?= e(fo_money($cfg['default_daily_rate'])) ?> per 8-hour day.</p></div><div class="fo-table-wrap"><table><thead><tr><th>Participant</th><th>Programme</th><th>Cohort</th><th>Date</th><th>Approved Minutes</th><th>Equivalent Days</th><th>Calculated Basis</th></tr></thead><tbody><?php foreach($rows as $x):$c=fo_calc((int)$x['approved_minutes'],(float)$cfg['default_daily_rate'],(int)$cfg['minimum_attendance_minutes']);?><tr><td><strong><?= e(trim($x['first_name'].' '.$x['last_name'])) ?></strong><span><?= e($x['email']) ?></span></td><td><?= e($x['programme_name']) ?></td><td><?= e($x['cohort_name']) ?></td><td><?= e(fo_date($x['attendance_date'])) ?></td><td><?= number_format((int)$x['approved_minutes']) ?></td><td><?= number_format((float)$c['days'],2) ?></td><td><?= e(fo_money($c['gross'])) ?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="fo-empty"><i class="fas fa-calendar-check"></i><strong>No approved attendance</strong></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>